package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="transfer_legs",uniqueConstraints=@UniqueConstraint(name="uq_transfer_leg_sequence",columnNames={"transfer_id","leg_sequence"})) public class TransferLeg{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) private TransferTransaction transfer; @Column(name="leg_sequence",nullable=false) private short legSequence; @Column(name="leg_type",nullable=false,length=40) private String legType; @ManyToOne(optional=false) @JoinColumn(name="debit_account_id") private TransferAccount debitAccount; @ManyToOne(optional=false) @JoinColumn(name="credit_account_id") private TransferAccount creditAccount; @Column(nullable=false,precision=19,scale=4) private BigDecimal amount; @Column(nullable=false,length=3) private String currency; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private LegStatus status; @Column(name="ledger_reference",unique=true,length=100) private String ledgerReference; @Column(name="posted_at") private Instant postedAt; @Column(name="failure_code",length=80) private String failureCode;
 public UUID getId(){return id;} public TransferTransaction getTransfer(){return transfer;} public void setTransfer(TransferTransaction v){transfer=v;} public short getLegSequence(){return legSequence;} public void setLegSequence(short v){legSequence=v;} public String getLegType(){return legType;} public void setLegType(String v){legType=v;} public TransferAccount getDebitAccount(){return debitAccount;} public void setDebitAccount(TransferAccount v){debitAccount=v;} public TransferAccount getCreditAccount(){return creditAccount;} public void setCreditAccount(TransferAccount v){creditAccount=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public String getCurrency(){return currency;} public void setCurrency(String v){currency=v;} public LegStatus getStatus(){return status;} public void setStatus(LegStatus v){status=v;} public String getLedgerReference(){return ledgerReference;} public void setLedgerReference(String v){ledgerReference=v;} public Instant getPostedAt(){return postedAt;} public void setPostedAt(Instant v){postedAt=v;} public String getFailureCode(){return failureCode;} public void setFailureCode(String v){failureCode=v;} public enum LegStatus{PENDING,POSTED,FAILED,REVERSED}
}
